export type PriceDetail = { amount: number | null; currency: 'USD' | 'EUR' | 'GBP' | 'UAH' | null; cadence: 'monthly' | 'yearly' | 'weekly' | 'quarterly' | 'half-yearly' | null; annualAmount: number | null; firstYearAmount?: number | null; introMonths?: number };
export type ComparableReport = { url?:string; priceDetails?: PriceDetail[]; findings?: Array<{kind:string;confidence?:'high'|'medium'|'low';summary?:string;evidence?:string;sourceUrl?:string}>; unknowns?:Array<{kind:string;title:string;summary:string;confidence:'low';sourceUrl:string}>; score:number; decision?:string };
export function annualCost(report: ComparableReport): { amount:number|null; currency:string|null; cadence:string|null; sourceAmount:number|null; firstYearAmount?:number|null; introMonths?:number; reason:string|null|'missing'|'mixed-currency'|'low-confidence' };
export function compareOfferReports(left: ComparableReport, right: ComparableReport): { leftCost:ReturnType<typeof annualCost>; rightCost:ReturnType<typeof annualCost>; priceWinner:'left'|'right'|'tie'|null; clarityWinner:'left'|'right'|'tie'; verdict:string; comparable:boolean };
